import React from 'react';

// import {Sheet} from '@mui/joy'
import FormLabel from '@mui/joy/FormLabel';
import Autocomplete from '@mui/joy/Autocomplete';
import FormControl from '@mui/joy/FormControl';
function BaseSelector (props) {
  let {value, items, valueType, onChange, label, sx} = props;
  const _handleChange = (e, val) => {
    if (e == null) {
      onChange([]);
    } 
    ;
    if (val == null) {
      onChange([]);
    } else {
      onChange((valueType === 'index') ? [items.indexOf(val)] : [val]);
    }
    
    return;
  }
  
 // check for bad items
 ;
 
  let options = items == null ? [] : items;
  
// incoming value has to be an array matching valueType
  let currentSelection = null;
;
  if (value === null) {
    currentSelection = null;
  } else {
    if (valueType === 'index') {
      currentSelection = items[value[0]];
    } else {
      currentSelection = value[0];
    }
  }

  let isx = {height: 'inherit', width: 'inherit', ...sx};
/*
  if (options.length === 0 ) {
    currentSelection =  'No items to display';
  } else {
    currentSelection = (options.includes(value)) ? value : null;
  }
 */
  let ePropsL = { 
    autoComplete: true,
    value: currentSelection,
    label: (label == null) ? ' ' : label, 
    size: "sm",
    variant: 'outlined',
    selectOnFocus: true,
    readOnly: false,
    sx: isx
    };
    //for debugging purposes
    
    const check = (option, value) => {
      if (option === value) {
        return true;
      } else
        return false;
     }
  
    
    let show = 
    <FormControl>
      {label != null ? <FormLabel>{label}</FormLabel> : null}
      <Autocomplete
      {...ePropsL }
      options={options != null ? options : []}
      isOptionEqualToValue={check}
      onChange={_handleChange}
      />
     </FormControl>
    return show;
}

export default BaseSelector;
// isOptionEqualToValue={(option, value) => (value.trim().length === 0 || option === value) ? true : false}