import React from 'react';
import  { useState, useEffect } from 'react';
import { distinctValues } from '@sassoftware/restafedit';
import BaseSelector from './BaseSelector';

function DistinctValues(props) {
  let { source, lib, table, column, value, label,  where, sx, onChange, _appContext,...eProps } = props;

  const [list, setList] = useState([]);
  const [sel, setSel] = useState(value);

  const _handleChange = (selx) => {
    setSel(selx);
    onChange(selx);
  };

  useEffect(() => {
    if (_appContext == null) {
      setList([]);
    } else {

      let appEnv = _appContext.getViyaSession(source); 
      if (appEnv === null || column == null || column.trim().length === 0) {
        setList([])
      } else {
        
        let w = (where == null) ? '' : where;
        let t = {name: table};
        if (appEnv.source === 'cas') {
          t.caslib = lib;
        } else {
          t.libref = lib;
        }

        distinctValues(column, appEnv, t, w)
          .then(r => {
            
            setList(r[column]);
          })
          .catch(err => {
            
            console.log(err);
            setList([]);
            setSel('');
          })
        }
      }

  }, [label, column, lib,table, where, _appContext]);

  let pr = {
    name: 'distinct',
    value: sel,
    items: list,
    label: label,
    onChange: _handleChange,
 
    style: sx,
    eProps: eProps

  }
  
  return (
    <BaseSelector {...pr} />
  );
}

export default DistinctValues;
